#!/usr/bin/env bash
set -uo pipefail
# InLightBio CN Deploy - 2026-11-18 homepage: demote ivonescimab CRL from featured banner
# and add Rocky commentary to the existing brief page.
# Overlay: index.html + pages/article/ivonescimab-fda-crl.html
# (therasik-inlight merge commit 427ed5e678842c243bf3f29051e08d548890978e, PR #120).
# Copies the live root to a NEW release dir; never deletes or edits the old root.
# Does not delete Aliyun 命令助手 commands or hidden wx-src pages.
# Writes rollback.sh in the new release dir.
# Pipe-safe: the overlay bundle is a quoted heredoc (not read from $0 or BASH_SOURCE),
# so this script behaves the same when run as a file or piped to bash.
# Finalized for merge short SHA 427ed5e. Do not re-run deploy_cn_20261117_p03b.sh
# after this change: that older script treats a missing #ivonescimab-crl-feature as failure.
EXPECTED_SHA256="ec6278d0d3e2987932495e8c0a0a3e1c7b90e8455f0c108caba1f71f26099f39"
PRE_PAGE_SHA="005259456cafd8806deff009b0e2cb47724fed84ac0ab8edef5503aa6ec9420b"
AFTER_PAGE_SHA="77b5b829e33d244517c45db5d09b354535cb870586f197510df01006208e0c08"
PRE_ARTICLE_SHA="efe530b2eea272a7a7f09467589bf87f25c41755adc1fa52455f1cd831ea66a1"
AFTER_ARTICLE_SHA="0335c6fb05eee1860362e23501948dc498613f8d05ef881be290034d4d353278"
VHOST_CONF="/www/server/panel/vhost/nginx/inlightbio.cn.conf"
NEW_REL_DIR="/www/wwwroot/inlightbio_cn_rel_20261118_427ed5e_r2"
LOG="/var/log/inlightbio_cn_deploy_20261118_ivo_downgrade.log"
CURRENT_ROOT=""; BACKUP_CONF=""
summary() { echo "$1 NEW_ROOT=$NEW_REL_DIR OLD_ROOT=${CURRENT_ROOT:-?} VHOST_BACKUP=${BACKUP_CONF:-none} LOG=$LOG"; }
abort() { echo "ERR: $1" | tee -a "$LOG"; summary "FAIL_$2_NOCHANGE"; exit 1; }
restore() { echo "ERR: $1" | tee -a "$LOG"; cp -a "$BACKUP_CONF" "$VHOST_CONF"; nginx -t >>"$LOG" 2>&1 && nginx -s reload >>"$LOG" 2>&1; summary "FAIL_$2_RESTORED"; exit 1; }
if ! { : > "$LOG"; } 2>/dev/null; then LOG=/tmp/inlightbio_cn_deploy_20261118_ivo_downgrade.log; : > "$LOG"; fi
case "$NEW_REL_DIR" in
  *MERGED_SHA*) abort "NEW_REL_DIR still has MERGED_SHA placeholder; finalize with the merged therasik-inlight SHA before running" PLACEHOLDER ;;
esac
TMPD=$(mktemp -d); trap 'rm -rf "$TMPD"' EXIT
# Decode the embedded bundle from this heredoc (works when the script is a file or stdin).
base64 -d > "$TMPD/o.tgz" <<'__BUNDLE_BASE64__' || abort "bundle base64 decode failed" B64
